mapper.select:
SELECT
    id, material_code, material_name, material_type, source_type,
    group_code, file_id, file_name, file_ext, file_size,
    link_url, link_status, visibility, cover_file_id, description,
    user_code, tenant_code, sort, create_time, create_by, update_time, update_by, remark, version
FROM mdm_material
WHERE deleted = 0
    AND tenant_code = #{tenantCode}
    AND user_code = #{userCode}
    AND material_name LIKE CONCAT('%', #{materialName}, '%')
    AND material_type = #{materialType}
    AND source_type = #{sourceType}
    AND group_code = #{groupCode}
    AND visibility = #{visibility}
    AND link_status = #{linkStatus}
    AND create_time >= #{timeFrom}
    AND create_time <= #{timeTo}
ORDER BY id DESC

SELECT id, material_code, material_name, material_type, source_type, group_code, file_id, file_name, file_ext, file_size, link_url, link_status, visibility, cover_file_id, description, user_code, tenant_code, sort, create_time, create_by, update_time, update_by, remark, version FROM mdm_material WHERE deleted = 0 AND tenant_code = #{tenantCode}
AND (visibility = 'PUBLIC' OR user_code = #{userCode})
AND material_type = #{materialType} AND group_code = #{groupCode} AND material_name LIKE CONCAT('%', #{materialName}, '%') ORDER BY id DESC
